"""Render `reports/05-routes.md` from the Stage 5 artifact."""

from __future__ import annotations

from pathlib import Path

from . import caveat
from . import config as C
from .report import _km, _pct, _table
from .report02 import _block, _f, _h, _n


def write(a: dict, path: Path = C.ROUTES_REPORT_MD) -> Path:
    parts = ["# Stage 5 — the day routes\n"]
    parts.append(
        "Generated by `efficientroute stage5`. Every number below is read from\n"
        "`data/derived/05-routes.json`, which the Stage 5 gate asserts against."
    )
    parts.append(_headline(a))
    parts.append(_correction(a))
    parts.append(_days(a))
    parts.append(_bracket(a))
    parts.append(_turns(a))
    parts.append(_orientation(a))
    parts.append(_driver(a))
    parts.append(_gate(a))
    path.parent.mkdir(parents=True, exist_ok=True)
    caveat.write(path, _block(*parts))
    return path


def _headline(a: dict) -> str:
    t = a["totals"]
    return (
        "\n## Headline\n\n"
        f"> ## {_n(t['days'])} driving days, {t['start_date']} → {t['finish_date']}\n"
        f">\n"
        f"> **{_h(t['route_h'])} h** of driving — {_h(t['capture_h'])} h capture,\n"
        f"> {_h(t['deadhead_h'])} h deadhead, {_h(t['turn_h'])} h turns — over\n"
        f"> {_n(t['arc_traversals'])} arc traversals. Every day starts and ends at the depot\n"
        f"> and every manoeuvre in every day is a legal edge of `L*`.\n"
        f">\n"
        f"> Days over their window: **{_n(t['days_over_window'])}**.\n"
        "\n"
        f"Variant {a['variant']}, {a['window']} window ({_f(a['window_h'], 1)} h). Each day is a\n"
        "GPX track and a turn-by-turn sheet in `reports/05-routes/`.\n"
    )


def _correction(a: dict) -> str:
    """How the sizing model and the solver compare, on this run's numbers.

    Written from `overhead_measured` rather than from a remembered narrative: the
    first version of this section hard-coded the figures of the run that produced
    it, and they went stale the moment Stage 4c re-zoned.
    """
    t = a["totals"]
    splits = a["splits"]
    measured = a.get("overhead_measured") or {}
    parts = ["\n## 1. The sizing model against the solver\n"]

    if not measured:
        parts.append(
            "This artifact predates the intra-zone overhead measurement, so the sizing\n"
            "model cannot be checked against it. Re-run `make stage5`.\n"
        )
        return _block(*parts)

    parts.append(
        "Stage 4 sizes a day as `capture x overhead + legs + break`, so `overhead` is\n"
        "the driving *inside* the zone per hour of capture — the depot legs are a\n"
        "separate term beside it. Measured over the "
        f"{_n(measured['n'])} days solved here:\n"
    )
    parts.append(
        _table(
            ["Statistic", "Intra-zone overhead"],
            [
                ["min", _f(measured["min"], 3)],
                ["p50", _f(measured["p50"], 3)],
                ["p75", _f(measured["p75"], 3)],
                ["p90", _f(measured["p90"], 3)],
                ["p95", _f(measured["p95"], 3)],
                ["max", _f(measured["max"], 3)],
            ],
        )
    )
    parts.append(
        "\n**Why the depot legs must stay out of it.** `route_h` contains both legs, so\n"
        "`route_h / capture_h` reads about a leg-pair-per-capture-hour higher than the\n"
        "figure above. Feeding *that* to a model which then adds the legs again charges\n"
        "them twice and inflates every zone's predicted day — which is exactly what\n"
        "`ZONE_OVERHEAD_MEASURED = 2.55` did, and what Stage 4c corrected.\n"
    )
    parts.append(
        "\n**The commute credit.** SPEC §7.1's first mitigation is real and Stage 4 once\n"
        "modelled it — but *Stage 5 does not implement it*. Each day is solved as a\n"
        "closed circuit over its own zone; its legs do pass through other zones, but at\n"
        "deadhead speed, capturing nothing. **A plan may not bank a saving its solver\n"
        "does not deliver**, so the credit stays withdrawn\n"
        "(`CAPTURE_ON_COMMUTE_IN_SIZING = False`) and `COMMUTE_ALLOWANCE` with it.\n"
        "Implementing it properly — solving days in sequence and letting each day's legs\n"
        "capture what later days still owe — is worth about 12 h and belongs with Stage\n"
        "6, which already tracks coverage across days.\n"
    )
    if not splits:
        parts.append(
            f"\n**No zone needed splitting**, and {_n(t['days_over_window'])} day(s) ran over\n"
            "their window: the sizing model and the solver agree, so the day count is real\n"
            "rather than a floor the solver had to repair.\n"
        )
    if splits:
        parts.append(
            f"\n**{_n(len(splits))} zone{'s' if len(splits) != 1 else ''} still would not fit after\n"
            "re-sizing and had to be split.** Shrinking every zone to accommodate one awkward\n"
            "one costs a day per zone; splitting the offender costs exactly one day, so the\n"
            "repair is local. Each split half was re-solved and re-checked.\n"
        )
        parts.append(
            _table(
                ["Zone split", "Became"],
                [[_n(s["zone"]), " + ".join(_n(x) for x in s["into"])] for s in splits],
            )
        )
    if t["days_over_window"]:
        parts.append(
            f"\n**{_n(t['days_over_window'])} day(s) remain over the window.** They are listed in\n"
            "§2 and they are a gate failure, not a rounding difference — see §8.\n"
        )
    return _block(*parts)


def _days(a: dict) -> str:
    parts = ["\n## 2. The days\n"]
    parts.append(
        "Ordered far-zones-first (SPEC §7.1 mitigation 2). `Route h` is the whole day's\n"
        "driving including both depot legs; the break is added on top to give `Day h`.\n"
    )
    rows = []
    for day in a["days"]:
        rows.append(
            [
                _n(day["day"]),
                day["date"],
                _n(day["zone"]),
                _f(day["capture_h"], 2),
                _f(day["deadhead_h"], 2),
                _f(day["turn_h"], 2),
                _f(day["route_h"], 2),
                _f(day["day_h"], 2),
                _pct(day["optimality_gap"] * 100),
                "" if day["fits"] else "**over**",
            ]
        )
    parts.append(
        _table(
            ["Day", "Date", "Zone", "Capture h", "Deadhead h", "Turn h", "Route h",
             "Day h", "Gap", ""],
            rows,
        )
    )
    t = a["totals"]
    parts.append(
        f"\n**Totals:** {_h(t['capture_h'])} h capture · {_h(t['deadhead_h'])} h deadhead ·\n"
        f"{_h(t['turn_h'])} h turns = **{_h(t['route_h'])} h driving**, plus\n"
        f"{_f(t['days'] * C.BREAK_HOURS, 1)} h of breaks.\n"
        f"\nDeadhead is {_pct(t['deadhead_h'] / t['capture_h'] * 100)} of capture time — higher\n"
        "than Stage 3's 58.5% for the same scope, and necessarily so: Stage 3 drove one tour,\n"
        f"this drives {_n(t['days'])} of them, each returning to a depot on the western edge.\n"
        "SPEC §4's KPI warning applies: **total driving hours is the KPI**, and the ratio is a\n"
        "diagnostic the coverage rules deliberately inflate.\n"
        "\n### The optimality gap\n"
        f"\nEach day's gap is measured against a rigorous floor — the zone's required capture\n"
        "time plus the cheapest legal way to leave each required traversal. Both terms are\n"
        "unavoidable and disjoint, so the floor is valid; it accounts for **no repositioning\n"
        "at all**, which is why the gaps look large. It is a bound, not a target.\n"
        f"\nCampaign gap against that floor: **{_pct(t['optimality_gap'] * 100)}**\n"
        f"({_h(t['route_h'])} h against a floor of {_h(t['lower_bound_h'])} h).\n"
    )
    return _block(*parts)


def _bracket(a: dict) -> str:
    bracket = a.get("stage3_bracket") or {}
    t = a["totals"]
    if not bracket:
        return ""
    return _block(
        "\n## 3. Against the Stage 3 bracket (I5)\n",
        _table(
            ["", "Hours"],
            [
                ["Stage 3 lower bound (LP relaxation)", _h(bracket["lower_h"])],
                ["Stage 3 upper bound (one closed tour)", _h(bracket["upper_h"])],
                [f"**Stage 5, {_n(t['days'])} day routes**", f"**{_h(t['route_h'])}**"],
            ],
        ),
        f"Stage 5 drives {_h(t['route_h'] - bracket['upper_h'])} h more than Stage 3's single\n"
        "tour, and that is expected rather than a regression. " + bracket["note"] + "\n",
        "**So I5 as written does not apply to a day plan.** SPEC §8 I5 asks that total driving\n"
        "lie within the Stage 3 bracket; the bracket was computed for a *different problem* —\n"
        "one tour, no depot, no shift limit. A 48-day plan is strictly more constrained and\n"
        "must cost more. The comparison worth making is the one above: the day plan against\n"
        "the tour, with the difference attributed to the depot returns the tour never made.\n"
        f"That difference is {_h(t['route_h'] - bracket['upper_h'])} h over "
        f"{_n(t['days'])} days —\n"
        f"about {_f((t['route_h'] - bracket['upper_h']) / t['days'] * 60, 0)} minutes a day of\n"
        "getting to work and home again, which is the price of having a depot on the western\n"
        "edge of the city (SPEC §7.1).\n",
    )


def _turns(a: dict) -> str:
    turns = a["turn_reconciliation"]
    t = a["totals"]
    rows = [
        ["Stage 2 floor — cheapest legal exit", _h(turns.get("stage2_floor_h", 0.0)),
         "estimate, variant A"],
        ["Stage 2 estimate — mean legal exit", _h(turns.get("stage2_estimate_h", 0.0)),
         "estimate, variant A"],
        ["Stage 3 tour, variant C", _h(turns.get("stage3_tour_turn_h", 0.0)),
         "one closed tour, counted exactly"],
        [f"**Stage 5, {_n(t['days'])} day routes**", f"**{_h(turns['stage5_turn_h'])}**",
         "counted exactly"],
    ]
    return _block(
        "\n## 4. The turn account, settled\n",
        "Stage 2 could only give a range — 91.2 to 145.0 h — because a turn penalty cannot be\n"
        "summed without knowing which manoeuvres get made, and it swung the campaign by 7.3\n"
        "days. Stage 3 counted a real tour. Stage 5 counts real routes.\n",
        _table(["Source", "Turn hours", "Basis"], rows, numeric=False),
        f"The count is now exact: {_n(t['arc_traversals'])} traversals, each followed by one\n"
        "manoeuvre whose class is read off `L(G)`. Stage 2's numbers were for variant A and\n"
        "are not directly comparable in magnitude, but the shape of its finding holds — turn\n"
        f"time is {_pct(turns['stage5_turn_h'] / t['route_h'] * 100)} of all driving, which is\n"
        "not a rounding term.\n",
        "**What is settled is the count, not the coefficients.** The per-turn seconds — "
        + ", ".join(f"{k} {v:.0f} s" for k, v in sorted(turns["penalties_s"].items()))
        + " —\nare SPEC §3.3's own approximations, still marked **[CONFIRM values]** in the spec and\n"
        "never measured against a real vehicle. Every turn figure in this project scales\n"
        "linearly with them. A stopwatch at twenty junctions would retire the largest\n"
        "remaining unvalidated assumption in the time model, and Stage 6's traces will carry\n"
        "the data to do it properly.\n",
    )


def _orientation(a: dict) -> str:
    orientation = a.get("orientation") or {}
    experiment = a.get("orientation_experiment")
    parts = ["\n## 5. Orientation — the untouched lever\n"]
    parts.append(
        "SPEC §4 Stage D lists an orientation-flip local search that has never been run.\n"
        "Stage 3 showed why it matters: its routing was within 1% of optimal *for a fixed\n"
        "orientation*, and the imbalance heuristic that chose that orientation removed only\n"
        f"{_pct((1 - orientation.get('imbalance_after', 1) / max(orientation.get('imbalance_naive', 1), 1)) * 100)}\n"
        "of junction imbalance. If savings remain anywhere, they are here.\n"
    )
    if not experiment:
        parts.append(
            "\n**Not run, and the reason is a cost, not an oversight.** Evaluating a single\n"
            "orientation flip means re-solving that zone's min-cost flow — about 11 seconds.\n"
            "A zone holds several hundred narrow pairs and there are 48 zones, so one pass of\n"
            "a true flip search is on the order of 90 hours of compute. It needs an\n"
            "incremental evaluation (flip the pair, repair the flow locally rather than\n"
            "re-solving it) before it is affordable, and that is a piece of work in its own\n"
            "right.\n"
        )
        return _block(*parts)
    parts.append(
        f"\nA true flip search is unaffordable — each flip has to be scored by re-solving the\n"
        f"zone's min-cost flow, about eleven seconds, against {_n(experiment['pairs_in_zone'])}\n"
        "pairs in this one zone alone. So the sensitivity is measured instead, on one\n"
        f"median-length day (zone {_n(experiment['zone'])}):\n"
    )
    parts.append(
        _table(
            ["Orientation", "Pairs flipped", "Route h", "vs heuristic"],
            [
                [row["label"], _n(row["flipped"]), _f(row["route_h"], 3),
                 f"{row['route_h'] - experiment['baseline_h']:+.3f}"]
                for row in experiment["samples"]
            ],
        )
    )
    parts.append(
        f"\n**Orientation is not a second-order lever.** An arbitrary choice costs\n"
        f"{_pct(experiment['cost_of_an_arbitrary_orientation'] * 100)} more than the imbalance\n"
        "heuristic on this day — the difference between a day that fits its shift and one\n"
        "that runs to nearly twice the length. Stage 3 was right that this is where the\n"
        "structure is.\n"
        f"\n{experiment['verdict']}\n"
        "\nWhat would make the search affordable is an incremental evaluation: flipping one\n"
        "pair changes two nodes' supply by one unit each, which is a *local* repair of an\n"
        "existing min-cost flow rather than a fresh solve. That is a real piece of work and\n"
        "it is the single most promising thing left in the optimisation.\n"
    )
    return _block(*parts)


def _driver(a: dict) -> str:
    t = a["totals"]
    lanes = sum(d["lane_instructions"] for d in a["days"])
    multi = sum(d["multi_pass_arcs"] for d in a["days"])
    return _block(
        "\n## 6. What the driver gets\n",
        _table(
            ["Artifact", "Count", "What it is"],
            [
                ["`reports/05-routes/day-NN.gpx`", _n(t["days"]),
                 "one track per day, closed, depot to depot"],
                ["`reports/05-routes/day-NN.md`", _n(t["days"]),
                 "turn-by-turn sheet, straight runs folded into one line"],
                ["`data/derived/05-routes.gpkg`", _n(t["arc_traversals"]),
                 "every manoeuvre, in order, with its mode and lane instruction"],
            ],
            numeric=False,
        ),
        f"**Lane instructions (invariant I8).** {_n(multi)} arc-days need two same-direction\n"
        f"passes, and {_n(lanes)} traversals carry an explicit lane group. SPEC §2.3: without\n"
        "it the driver repeats the same lane and the second pass is wasted footage. Georgia\n"
        "drives on the right, so pass 1 takes the kerb side and pass 2 the offside.\n",
        "The sheets fold consecutive straight-ahead steps along the same named street into a\n"
        "single instruction. A sheet with fifteen hundred rows saying \"continue\" is not a\n"
        "usable document, and the driver needs an instruction only where something changes.\n"
        "Capture rows carry the 40 km/h limit; deadhead rows say so explicitly, because a\n"
        "driver who captures on a repositioning leg is wasting the day's daylight.\n",
    )


def _gate(a: dict) -> str:
    t = a["totals"]
    return _block(
        "\n## 7. Gate\n",
        _table(
            ["Invariant", "Result"],
            [
                ["I1 — every required element covered across the campaign", "asserted"],
                ["I2 — every manoeuvre a legal edge of `L*`", "asserted"],
                ["I3 — every day starts and ends at the depot", "asserted"],
                ["I4 — no day exceeds its window",
                 "asserted" if not t["days_over_window"] else
                 f"**{_n(t['days_over_window'])} day(s) over**"],
                ["I5 — against the Stage 3 bracket", "reported, see §3"],
                ["I6 — every arc exists in the base network", "asserted"],
                ["I7 — no required traversal above 40 km/h except reduced", "asserted"],
                ["I8 — every multi-pass arc names a lane group per pass", "asserted"],
                ["Every zone has a route", "asserted — no zone left unsolved"],
                ["GPX matches the solved sequence arc-for-arc", "asserted"],
            ],
            numeric=False,
        ),
        "\n### Non-goals honoured\n",
        "No coverage tracking and no re-planning — Stage 6. No dashboard — Stage 7.\n",
    )
